Form.Script:
include "common/Common.js";

// ---------- 1) 직접 호출: 계좌 목록 ----------
function btn_search_OnClick(obj)
{
    Transaction("svcAccountList",
                "http://localhost:8080/bank/miplatform/account/list",
                "",
                "ds_account=ds_account",
                "",
                "fn_callback");
}

// ---------- 2) 직접 호출 + URL 문자열 연결: 계좌 상세/거래내역 ----------
function grd_account_OnClick(obj, nRow, nCell)
{
    var sAcctNo = ds_account.GetColumn(nRow, "acctNo");
    ds_cond.ClearData();
    ds_cond.AddRow();
    ds_cond.SetColumn(0, "acctNo", sAcctNo);

    var sBase = "http://localhost:8080/bank";
    var sSvc  = "detail";
    Transaction("svcAccountDetail",
                sBase + "/miplatform/account/" + sSvc,
                "ds_cond=ds_cond",
                "ds_account=ds_account ds_hist=ds_hist",
                "",
                "fn_callback");
}

// ---------- 3) 공통 래퍼 호출: 이체 ----------
function btn_transfer_OnClick(obj)
{
    var nRow = ds_account.row;
    ds_transfer.ClearData();
    ds_transfer.AddRow();
    ds_transfer.SetColumn(0, "fromAcctNo", ds_account.GetColumn(nRow, "acctNo"));
    ds_transfer.SetColumn(0, "toAcctNo", edt_to.Text);
    ds_transfer.SetColumn(0, "amount", edt_amount.Text);
    ds_transfer.SetColumn(0, "memo", edt_memo.Text);

    gfn_transaction("svcAccountTransfer",
                    "/miplatform/account/transfer",
                    "ds_transfer=ds_transfer",
                    "",
                    "",
                    "fn_callback");
}

function fn_callback(strSvcId, nErrorCode, strErrorMsg)
{
    if (gfn_isError(nErrorCode, strErrorMsg)) {
        return;
    }
    if (strSvcId == "svcAccountTransfer") {
        alert("이체가 완료되었습니다.");
        btn_search_OnClick(btn_search);
    }
}
